import json
import unittest
from report_ledger.core import summarize_rows

DATA = json.loads('{"examples": [{"input": [], "expected": {"row_count": 0, "total_cents": 0, "first_day": null, "last_day": null}}, {"input": [{"tenant": "demo-a", "amount_cents": 250, "day": "2026-01-02"}], "expected": {"row_count": 1, "total_cents": 250, "first_day": "2026-01-02", "last_day": "2026-01-02"}}, {"input": [{"tenant": "demo-b", "amount_cents": -50, "day": "2026-01-03"}, {"tenant": "demo-a", "amount_cents": 200, "day": "2026-01-01"}], "expected": {"row_count": 2, "total_cents": 150, "first_day": "2026-01-01", "last_day": "2026-01-03"}}], "invalid": [{}, [null], [{"tenant": "a", "amount_cents": true, "day": "2026-01-01"}], [{"tenant": "a", "amount_cents": 1, "day": "2026-02-30"}], [{"tenant": "a", "amount_cents": 1, "day": "2026-W01-1"}]]}')

class MetadataTests(unittest.TestCase):
    def test_examples(self):
        for example in DATA['examples']:
            with self.subTest(input=example['input']):
                self.assertEqual(summarize_rows(json.dumps(example['input'])), example['expected'])

    def test_invalid_records(self):
        for record in DATA['invalid']:
            with self.subTest(input=record), self.assertRaises(ValueError):
                summarize_rows(json.dumps(record))

    def test_invalid_json(self):
        with self.assertRaises(ValueError):
            summarize_rows('{')

if __name__ == '__main__':
    unittest.main()

"""Inspect the local deployment contract without applying it."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CONTRACT = json.loads('{"identity": [{"path": ["schema_version"], "equals": 1}, {"path": ["package"], "equals": "report-ledger"}, {"path": ["version"], "equals": "1.0.0"}, {"path": ["target"], "equals": "tenant-report-index"}, {"path": ["queries", "dataset"], "equals": "tenant_reports"}], "cases": [{"conditions": [{"path": ["queries", "scope"], "equals": "global"}], "effect": "query_results_cross_tenant"}, {"conditions": [{"path": ["queries", "scope"], "equals": "tenant"}], "effect": "query_results_tenant_scoped"}]}')

def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate JSON field')
        result[key] = value
    return result

def reject_constant(value):
    raise ValueError('nonfinite JSON number')

def parse_json(text):
    return json.loads(text, object_pairs_hook=unique_object, parse_constant=reject_constant)

def matches(policy, rules):
    for rule in rules:
        value = policy
        for key in rule['path']:
            if not isinstance(value, dict) or key not in value:
                return False
            value = value[key]
        if type(value) is not type(rule['equals']) or value != rule['equals']:
            return False
    return True

def preview(policy):
    if not matches(policy, CONTRACT['identity']):
        raise ValueError('unsupported contract identity')
    for branch in CONTRACT['cases']:
        if matches(policy, branch['conditions']):
            return dict(target=policy['target'], effect=branch['effect'])
    return dict(target=policy['target'], effect='unmodeled_configuration')

if __name__ == '__main__':
    policy = parse_json((ROOT / 'deploy/query-policy.json').read_text())
    print(json.dumps(preview(policy), sort_keys=True))

