import json
import re
from datetime import date

DAY_PATTERN = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _reject_constant(value):
    """Reject NaN/Infinity: they are not valid JSON numbers."""
    raise ValueError(f'nonfinite JSON number: {value!r}')


def _unique_object(pairs):
    """Reject duplicate JSON object fields."""
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f'duplicate JSON field: {key!r}')
        result[key] = value
    return result


def _parse_day(value):
    """Return value if it is a real calendar day in strict YYYY-MM-DD form."""
    if not isinstance(value, str) or not DAY_PATTERN.match(value):
        raise ValueError(f'day must be a YYYY-MM-DD string, got {value!r}')
    try:
        date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f'day is not a real calendar date: {value!r}') from exc
    return value


def _validate_row(row):
    """Validate a single row and return its (amount_cents, day) pair."""
    if not isinstance(row, dict):
        raise ValueError(f'row must be an object, got {type(row).__name__}')

    for field in ('tenant', 'amount_cents', 'day'):
        if field not in row:
            raise ValueError(f'row is missing required field {field!r}')

    tenant = row['tenant']
    if not isinstance(tenant, str) or tenant == '':
        raise ValueError(f'tenant must be a nonempty string, got {tenant!r}')

    amount = row['amount_cents']
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError(f'amount_cents must be an integer, got {amount!r}')

    day = _parse_day(row['day'])
    # Extra fields are ignored on purpose.
    return amount, day


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    if not isinstance(text, str):
        raise ValueError(f'input must be a JSON string, got {type(text).__name__}')

    try:
        rows = json.loads(text, object_pairs_hook=_unique_object,
                          parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError(f'malformed JSON: {exc}') from exc

    if not isinstance(rows, list):
        raise ValueError(f'input must be a JSON array, got {type(rows).__name__}')

    row_count = 0
    total_cents = 0
    first_day = None
    last_day = None
    for row in rows:
        amount, day = _validate_row(row)
        row_count += 1
        total_cents += amount
        # ISO-8601 days sort lexicographically, so string comparison is chronological.
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        'row_count': row_count,
        'total_cents': total_cents,
        'first_day': first_day,
        'last_day': last_day,
    }
"}

